using System.Linq.Expressions;
using System.Reflection;

namespace Automatonymous;

/// <summary>Defines and executes a standalone finite-state machine for <typeparamref name="TInstance"/>.</summary>
/// <typeparam name="TInstance">The caller-owned instance type.</typeparam>
public abstract class AutomatonymousStateMachine<TInstance>
    where TInstance : class
{
    private readonly Dictionary<(State State, Event Event), ConfiguredBehavior<TInstance>> _stateBehaviors = [];
    private readonly Dictionary<Event, ConfiguredBehavior<TInstance>> _anyBehaviors = [];
    private IStateAccessor<TInstance>? _stateAccessor;
    private bool _frozen;

    /// <summary>Initializes a new machine and conventionally populates declared State and Event properties.</summary>
    protected AutomatonymousStateMachine()
    {
        Initial = new State(nameof(Initial));
        Final = new State(nameof(Final));
        InitializeDeclaredProperties();
    }

    /// <summary>Gets the distinguished initial state. A null stored state is interpreted as Initial.</summary>
    public State Initial { get; }

    /// <summary>Gets the distinguished final state.</summary>
    public State Final { get; }

    /// <summary>Declares a state property using the familiar Automatonymous syntax.</summary>
    protected void State(Expression<Func<State>> stateExpression)
    {
        EnsureConfigurable();
        DeclareProperty(stateExpression, property => new State(property.Name));
    }

    /// <summary>Declares an untyped event property using the familiar Automatonymous syntax.</summary>
    protected void Event(Expression<Func<Event>> eventExpression)
    {
        EnsureConfigurable();
        DeclareProperty(eventExpression, property => new Event(property.Name));
    }

    /// <summary>Declares a typed event property using the familiar Automatonymous syntax.</summary>
    protected void Event<TData>(Expression<Func<Event<TData>>> eventExpression)
    {
        EnsureConfigurable();
        DeclareProperty(eventExpression, property => new Event<TData>(property.Name));
    }

    /// <summary>Configures the instance property used to read and write state.</summary>
    protected void InstanceState(Expression<Func<TInstance, State>> stateExpression)
    {
        EnsureConfigurable();
        ArgumentNullException.ThrowIfNull(stateExpression);

        if (stateExpression.Body is not MemberExpression { Member: PropertyInfo property } ||
            property.PropertyType != typeof(State) ||
            property.SetMethod is null)
        {
            throw new ArgumentException("InstanceState requires a writable State property expression.", nameof(stateExpression));
        }

        _stateAccessor = new PropertyStateAccessor<TInstance>(stateExpression.Compile(), property);
    }

    /// <summary>Begins an untyped event behavior.</summary>
    protected EventActivityBinder<TInstance> When(Event @event)
    {
        ArgumentNullException.ThrowIfNull(@event);
        if (@event.DataType is not null)
        {
            throw new ArgumentException("Use the typed When overload for a typed event.", nameof(@event));
        }

        return new EventActivityBinder<TInstance>(@event);
    }

    /// <summary>Begins a typed event behavior.</summary>
    protected EventActivityBinder<TInstance, TData> When<TData>(Event<TData> @event)
    {
        ArgumentNullException.ThrowIfNull(@event);
        return new EventActivityBinder<TInstance, TData>(@event);
    }

    /// <summary>Configures an untyped event to be ignored.</summary>
    protected EventActivityBinder<TInstance> Ignore(Event @event) => When(@event).Ignore();

    /// <summary>Configures a typed event to be ignored.</summary>
    protected EventActivityBinder<TInstance, TData> Ignore<TData>(Event<TData> @event) => When(@event).Ignore();

    /// <summary>Configures behaviors in the distinguished initial state.</summary>
    protected void Initially(params EventActivityBinder<TInstance>[] behaviors) => During(Initial, behaviors);

    /// <summary>Configures behaviors for a specific state.</summary>
    protected void During(State state, params EventActivityBinder<TInstance>[] behaviors)
    {
        EnsureConfigurable();
        ArgumentNullException.ThrowIfNull(state);
        AddBehaviors(behaviors, behavior => _stateBehaviors.Add((state, behavior.Event), behavior));
    }

    /// <summary>Configures fallback behaviors used when the current state has no specific behavior.</summary>
    protected void DuringAny(params EventActivityBinder<TInstance>[] behaviors)
    {
        EnsureConfigurable();
        AddBehaviors(behaviors, behavior => _anyBehaviors.Add(behavior.Event, behavior));
    }

    /// <summary>Raises an untyped event and awaits all configured effects.</summary>
    public Task RaiseEvent(TInstance instance, Event @event)
    {
        ArgumentNullException.ThrowIfNull(@event);
        if (@event.DataType is not null)
        {
            throw new ArgumentException("Typed events must be raised with event data.", nameof(@event));
        }

        return RaiseEventCore(instance, @event, null);
    }

    /// <summary>Raises a typed event and awaits all configured effects.</summary>
    public Task RaiseEvent<TData>(TInstance instance, Event<TData> @event, TData data)
    {
        ArgumentNullException.ThrowIfNull(@event);
        return RaiseEventCore(instance, @event, data);
    }

    private async Task RaiseEventCore(TInstance instance, Event @event, object? data)
    {
        ArgumentNullException.ThrowIfNull(instance);
        _frozen = true;
        var accessor = _stateAccessor ?? throw new InvalidOperationException("InstanceState must be configured before raising events.");
        var state = accessor.Get(instance) ?? Initial;

        if (!_stateBehaviors.TryGetValue((state, @event), out var behavior) &&
            !_anyBehaviors.TryGetValue(@event, out behavior))
        {
            throw new UnhandledEventException(@event, state);
        }

        if (behavior.IsIgnored)
        {
            return;
        }

        foreach (var step in behavior.Steps)
        {
            switch (step.Kind)
            {
                case BehaviorStepKind.Callback:
                    await step.Invoke!(instance, data).ConfigureAwait(false);
                    break;
                case BehaviorStepKind.Transition:
                    accessor.Set(instance, step.Target!);
                    break;
                case BehaviorStepKind.Finalize:
                    accessor.Set(instance, Final);
                    break;
                default:
                    throw new InvalidOperationException("Unknown behavior step.");
            }
        }
    }

    private void AddBehaviors(
        EventActivityBinder<TInstance>[] behaviors,
        Action<ConfiguredBehavior<TInstance>> add)
    {
        ArgumentNullException.ThrowIfNull(behaviors);
        foreach (var binder in behaviors)
        {
            ArgumentNullException.ThrowIfNull(binder);
            binder.Validate();
            add(new ConfiguredBehavior<TInstance>(binder.Event, binder.IsIgnored, [.. binder.Steps]));
        }
    }

    private void InitializeDeclaredProperties()
    {
        const BindingFlags flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
        foreach (var property in GetType().GetProperties(flags))
        {
            if (property.GetIndexParameters().Length != 0 || property.SetMethod is null || property.GetValue(this) is not null)
            {
                continue;
            }

            object? value = property.PropertyType == typeof(State)
                ? new State(property.Name)
                : property.PropertyType == typeof(Event)
                    ? new Event(property.Name)
                    : CreateTypedEvent(property);

            if (value is not null)
            {
                property.SetValue(this, value);
            }
        }
    }

    private static object? CreateTypedEvent(PropertyInfo property)
    {
        if (!property.PropertyType.IsGenericType || property.PropertyType.GetGenericTypeDefinition() != typeof(Event<>))
        {
            return null;
        }

        return Activator.CreateInstance(
            property.PropertyType,
            BindingFlags.Instance | BindingFlags.NonPublic,
            binder: null,
            args: [property.Name],
            culture: null);
    }

    private void DeclareProperty<TMember>(
        Expression<Func<TMember>> expression,
        Func<PropertyInfo, TMember> factory)
        where TMember : class
    {
        ArgumentNullException.ThrowIfNull(expression);

        if (expression.Body is not MemberExpression { Member: PropertyInfo property } ||
            property.PropertyType != typeof(TMember) ||
            property.SetMethod is null)
        {
            throw new ArgumentException("A writable state-machine property expression is required.", nameof(expression));
        }

        if (property.GetValue(this) is null)
        {
            property.SetValue(this, factory(property));
        }
    }

    private void EnsureConfigurable()
    {
        if (_frozen)
        {
            throw new InvalidOperationException("State-machine configuration cannot change after event execution begins.");
        }
    }
}

internal sealed record ConfiguredBehavior<TInstance>(
    Event Event,
    bool IsIgnored,
    IReadOnlyList<BehaviorStep<TInstance>> Steps)
    where TInstance : class;

internal interface IStateAccessor<TInstance>
    where TInstance : class
{
    State? Get(TInstance instance);

    void Set(TInstance instance, State state);
}

internal sealed class PropertyStateAccessor<TInstance>(
    Func<TInstance, State> getter,
    PropertyInfo property) : IStateAccessor<TInstance>
    where TInstance : class
{
    public State? Get(TInstance instance) => getter(instance);

    public void Set(TInstance instance, State state) => property.SetValue(instance, state);
}

namespace Automatonymous;

/// <summary>Provides the values visible to an untyped behavior callback.</summary>
/// <typeparam name="TInstance">The state-machine instance type.</typeparam>
public class BehaviorContext<TInstance>
    where TInstance : class
{
    internal BehaviorContext(TInstance instance, Event @event)
    {
        Instance = instance;
        Event = @event;
    }

    /// <summary>Gets the caller-owned instance receiving the event.</summary>
    public TInstance Instance { get; }

    /// <summary>Gets the event being raised.</summary>
    public Event Event { get; }
}

/// <summary>Provides the values visible to a typed behavior callback.</summary>
/// <typeparam name="TInstance">The state-machine instance type.</typeparam>
/// <typeparam name="TData">The event data type.</typeparam>
public sealed class BehaviorContext<TInstance, TData> : BehaviorContext<TInstance>
    where TInstance : class
{
    internal BehaviorContext(TInstance instance, Event<TData> @event, TData data)
        : base(instance, @event) => Data = data;

    /// <summary>Gets the data supplied with the event.</summary>
    public TData Data { get; }
}

namespace Automatonymous;

/// <summary>Identifies an event with no data payload.</summary>
public class Event
{
    internal Event(string name, Type? dataType = null)
    {
        Name = name;
        DataType = dataType;
    }

    /// <summary>Gets the declaration name of the event.</summary>
    public string Name { get; }

    internal Type? DataType { get; }

    /// <inheritdoc />
    public override string ToString() => Name;
}

/// <summary>Identifies an event carrying data of type <typeparamref name="TData"/>.</summary>
/// <typeparam name="TData">The event data type.</typeparam>
public sealed class Event<TData> : Event
{
    internal Event(string name) : base(name, typeof(TData))
    {
    }
}

namespace Automatonymous;

/// <summary>Builds the ordered behavior for one event.</summary>
/// <typeparam name="TInstance">The state-machine instance type.</typeparam>
public class EventActivityBinder<TInstance>
    where TInstance : class
{
    private readonly List<BehaviorStep<TInstance>> _steps = [];

    internal EventActivityBinder(Event @event) => Event = @event;

    internal Event Event { get; }

    internal bool IsIgnored { get; private set; }

    internal IReadOnlyList<BehaviorStep<TInstance>> Steps => _steps;

    /// <summary>Adds a synchronous callback to the behavior.</summary>
    public EventActivityBinder<TInstance> Then(Action<BehaviorContext<TInstance>> callback)
    {
        ArgumentNullException.ThrowIfNull(callback);
        AddStep(BehaviorStep<TInstance>.Callback((instance, _) =>
        {
            callback(new BehaviorContext<TInstance>(instance, Event));
            return Task.CompletedTask;
        }));
        return this;
    }

    /// <summary>Adds an asynchronous callback to the behavior.</summary>
    public EventActivityBinder<TInstance> ThenAsync(Func<BehaviorContext<TInstance>, Task> callback)
    {
        ArgumentNullException.ThrowIfNull(callback);
        AddStep(BehaviorStep<TInstance>.Callback((instance, _) =>
            callback(new BehaviorContext<TInstance>(instance, Event))));
        return this;
    }

    /// <summary>Adds a transition to the target state.</summary>
    public EventActivityBinder<TInstance> TransitionTo(State state)
    {
        ArgumentNullException.ThrowIfNull(state);
        AddStep(BehaviorStep<TInstance>.Transition(state));
        return this;
    }

    /// <summary>Adds a transition to the distinguished final state.</summary>
    public EventActivityBinder<TInstance> Finalize()
    {
        AddStep(BehaviorStep<TInstance>.FinalizeStep());
        return this;
    }

    /// <summary>Marks the event as accepted without effects or a state change.</summary>
    public EventActivityBinder<TInstance> Ignore()
    {
        if (_steps.Count != 0)
        {
            throw new InvalidOperationException("Ignore cannot be combined with behavior steps.");
        }

        IsIgnored = true;
        return this;
    }

    internal void Validate()
    {
        if (IsIgnored && _steps.Count != 0)
        {
            throw new InvalidOperationException("Ignore cannot be combined with behavior steps.");
        }
    }

    private protected void AddStep(BehaviorStep<TInstance> step)
    {
        if (IsIgnored)
        {
            throw new InvalidOperationException("Behavior steps cannot be added after Ignore.");
        }

        _steps.Add(step);
    }
}

/// <summary>Builds the ordered behavior for one typed event.</summary>
/// <typeparam name="TInstance">The state-machine instance type.</typeparam>
/// <typeparam name="TData">The event data type.</typeparam>
public sealed class EventActivityBinder<TInstance, TData> : EventActivityBinder<TInstance>
    where TInstance : class
{
    private readonly Event<TData> _event;

    internal EventActivityBinder(Event<TData> @event) : base(@event) => _event = @event;

    /// <summary>Adds a synchronous callback that can inspect the event data.</summary>
    public EventActivityBinder<TInstance, TData> Then(Action<BehaviorContext<TInstance, TData>> callback)
    {
        ArgumentNullException.ThrowIfNull(callback);
        AddStep(BehaviorStep<TInstance>.Callback((instance, data) =>
        {
            callback(new BehaviorContext<TInstance, TData>(instance, _event, (TData)data!));
            return Task.CompletedTask;
        }));
        return this;
    }

    /// <summary>Adds an asynchronous callback that can inspect the event data.</summary>
    public EventActivityBinder<TInstance, TData> ThenAsync(Func<BehaviorContext<TInstance, TData>, Task> callback)
    {
        ArgumentNullException.ThrowIfNull(callback);
        AddStep(BehaviorStep<TInstance>.Callback((instance, data) =>
            callback(new BehaviorContext<TInstance, TData>(instance, _event, (TData)data!))));
        return this;
    }

    /// <inheritdoc />
    public new EventActivityBinder<TInstance, TData> TransitionTo(State state)
    {
        base.TransitionTo(state);
        return this;
    }

    /// <inheritdoc />
    public new EventActivityBinder<TInstance, TData> Finalize()
    {
        base.Finalize();
        return this;
    }

    /// <inheritdoc />
    public new EventActivityBinder<TInstance, TData> Ignore()
    {
        base.Ignore();
        return this;
    }
}

internal enum BehaviorStepKind
{
    Callback,
    Transition,
    Finalize
}

internal sealed record BehaviorStep<TInstance>(
    BehaviorStepKind Kind,
    Func<TInstance, object?, Task>? Invoke,
    State? Target)
    where TInstance : class
{
    internal static BehaviorStep<TInstance> Callback(Func<TInstance, object?, Task> callback) =>
        new(BehaviorStepKind.Callback, callback, null);

    internal static BehaviorStep<TInstance> Transition(State target) =>
        new(BehaviorStepKind.Transition, null, target);

    internal static BehaviorStep<TInstance> FinalizeStep() =>
        new(BehaviorStepKind.Finalize, null, null);
}

namespace Automatonymous;

/// <summary>Identifies a state in a state-machine definition.</summary>
public sealed class State
{
    internal State(string name) => Name = name;

    /// <summary>Gets the declaration name of the state.</summary>
    public string Name { get; }

    /// <inheritdoc />
    public override string ToString() => Name;
}

namespace Automatonymous;

/// <summary>Thrown when an event has no behavior or ignore declaration for the current state.</summary>
public sealed class UnhandledEventException : InvalidOperationException
{
    internal UnhandledEventException(Event @event, State state)
        : base($"The event '{@event.Name}' is not handled in state '{state.Name}'.")
    {
        Event = @event;
        State = state;
    }

    /// <summary>Gets the unhandled event.</summary>
    public Event Event { get; }

    /// <summary>Gets the state in which the event was raised.</summary>
    public State State { get; }
}

using Automatonymous;
using Xunit;

namespace Autonomata.Tests;

public sealed class StateMachineTests
{
    [Fact]
    public async Task Familiar_dsl_executes_initial_behavior_and_transition()
    {
        var machine = new OrderMachine();
        var instance = new OrderState();

        await machine.RaiseEvent(instance, machine.Submit);

        Assert.Equal(["submitted"], instance.Effects);
        Assert.Same(machine.Active, instance.CurrentState);
    }

    [Fact]
    public async Task Typed_event_exposes_instance_event_and_data()
    {
        var machine = new OrderMachine();
        var instance = new OrderState { CurrentState = machine.Active };

        await machine.RaiseEvent(instance, machine.QuantityChanged, 7);

        Assert.Equal(7, instance.Quantity);
        Assert.Same(machine.QuantityChanged, instance.LastEvent);
    }

    [Fact]
    public async Task Typed_async_behavior_is_awaited_and_can_transition()
    {
        var machine = new TypedAsyncMachine();
        var instance = new OrderState();

        await machine.RaiseEvent(instance, machine.Start, 42);

        Assert.Equal(42, instance.Quantity);
        Assert.Same(machine.Active, instance.CurrentState);
    }

    [Fact]
    public async Task Typed_ignore_accepts_data_without_effect_or_state_change()
    {
        var machine = new TypedAsyncMachine();
        var instance = new OrderState { CurrentState = machine.Active };

        await machine.RaiseEvent(instance, machine.IgnoreMe, "ignored data");

        Assert.Empty(instance.Effects);
        Assert.Same(machine.Active, instance.CurrentState);
    }

    [Fact]
    public async Task Typed_finalize_persists_distinguished_final_state()
    {
        var machine = new TypedFinalizeMachine();
        var instance = new OrderState();

        await machine.RaiseEvent(instance, machine.Complete, 23);

        Assert.Same(machine.Final, instance.CurrentState);
    }

    [Fact]
    public async Task Async_behavior_is_awaited_in_declaration_order()
    {
        var release = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var machine = new OrderedMachine(release.Task);
        var instance = new OrderState();

        var raise = machine.RaiseEvent(instance, machine.Start);
        await machine.AsyncStarted.Task.WaitAsync(TimeSpan.FromSeconds(5));

        Assert.False(raise.IsCompleted);
        Assert.Equal(["before", "async-start"], instance.Effects);
        Assert.Null(instance.CurrentState);

        release.SetResult();
        await raise;

        Assert.Equal(["before", "async-start", "async-end"], instance.Effects);
        Assert.Same(machine.Active, instance.CurrentState);
    }

    [Fact]
    public async Task State_specific_behavior_wins_over_during_any_fallback()
    {
        var machine = new OrderMachine();
        var active = new OrderState { CurrentState = machine.Active };
        var suspended = new OrderState { CurrentState = machine.Suspended };

        await machine.RaiseEvent(active, machine.Refresh);
        await machine.RaiseEvent(suspended, machine.Refresh);

        Assert.Equal(["active"], active.Effects);
        Assert.Equal(["fallback"], suspended.Effects);
    }

    [Fact]
    public async Task Ignore_accepts_event_without_effect_or_state_change()
    {
        var machine = new OrderMachine();
        var instance = new OrderState { CurrentState = machine.Active };

        await machine.RaiseEvent(instance, machine.Cancel);

        Assert.Empty(instance.Effects);
        Assert.Same(machine.Active, instance.CurrentState);
    }

    [Fact]
    public async Task State_specific_ignore_wins_over_during_any_behavior()
    {
        var machine = new IgnorePrecedenceMachine();
        var instance = new OrderState { CurrentState = machine.Active };

        await machine.RaiseEvent(instance, machine.Refresh);

        Assert.Empty(instance.Effects);
        Assert.Same(machine.Active, instance.CurrentState);
    }

    [Fact]
    public async Task Unhandled_event_identifies_event_and_state()
    {
        var machine = new OrderMachine();
        var instance = new OrderState { CurrentState = machine.Suspended };

        var exception = await Assert.ThrowsAsync<UnhandledEventException>(
            () => machine.RaiseEvent(instance, machine.Cancel));

        Assert.Same(machine.Cancel, exception.Event);
        Assert.Same(machine.Suspended, exception.State);
        Assert.Contains("Cancel", exception.Message, StringComparison.Ordinal);
        Assert.Contains("Suspended", exception.Message, StringComparison.Ordinal);
        Assert.Same(machine.Suspended, instance.CurrentState);
    }

    [Fact]
    public async Task Finalize_transitions_to_distinguished_final_state()
    {
        var machine = new OrderMachine();
        var instance = new OrderState { CurrentState = machine.Active };

        await machine.RaiseEvent(instance, machine.Complete);

        Assert.Same(machine.Final, instance.CurrentState);
    }

    [Fact]
    public async Task Callback_failure_preserves_prior_effects_and_stops_later_steps()
    {
        var machine = new FailureMachine();
        var instance = new OrderState();

        var exception = await Assert.ThrowsAsync<TestFailureException>(
            () => machine.RaiseEvent(instance, machine.Fail));

        Assert.Equal("expected", exception.Message);
        Assert.Equal(["before"], instance.Effects);
        Assert.Null(instance.CurrentState);
    }

    [Fact]
    public async Task Typed_event_preserves_payload_identity_through_ordered_callbacks()
    {
        var payload = new QuantityUpdate(17);
        var machine = new TypedPayloadMachine();
        var instance = new OrderState();

        await machine.RaiseEvent(instance, machine.Update, payload);

        Assert.Same(payload, machine.ObservedPayload);
        Assert.Equal(["first:17", "second:17"], instance.Effects);
        Assert.Same(machine.Active, instance.CurrentState);
    }

    [Fact]
    public void Convention_names_and_populates_declared_machine_members()
    {
        var machine = new OrderMachine();

        Assert.Equal("Active", machine.Active.Name);
        Assert.Equal("Submit", machine.Submit.Name);
        Assert.Equal("QuantityChanged", machine.QuantityChanged.Name);
        Assert.Equal("Initial", machine.Initial.Name);
        Assert.Equal("Final", machine.Final.Name);
        Assert.Equal("Active", machine.Active.ToString());
        Assert.Equal("Submit", machine.Submit.ToString());
    }

    private sealed class OrderState
    {
        public State? CurrentState { get; set; }

        public List<string> Effects { get; } = [];

        public int Quantity { get; set; }

        public Event? LastEvent { get; set; }
    }

    private sealed class OrderMachine : AutomatonymousStateMachine<OrderState>
    {
        public OrderMachine()
        {
            InstanceState(instance => instance.CurrentState!);

            Initially(
                When(Submit)
                    .Then(context => context.Instance.Effects.Add("submitted"))
                    .TransitionTo(Active));

            During(
                Active,
                When(QuantityChanged).Then(context =>
                {
                    context.Instance.Quantity = context.Data;
                    context.Instance.LastEvent = context.Event;
                }),
                When(Refresh).Then(context => context.Instance.Effects.Add("active")),
                When(Cancel).Ignore(),
                When(Complete).Finalize());

            DuringAny(When(Refresh).Then(context => context.Instance.Effects.Add("fallback")));
        }

        public State Active { get; private set; } = null!;

        public State Suspended { get; private set; } = null!;

        public Event Submit { get; private set; } = null!;

        public Event Refresh { get; private set; } = null!;

        public Event Cancel { get; private set; } = null!;

        public Event Complete { get; private set; } = null!;

        public Event<int> QuantityChanged { get; private set; } = null!;
    }

    private sealed class OrderedMachine : AutomatonymousStateMachine<OrderState>
    {
        public OrderedMachine(Task release)
        {
            InstanceState(instance => instance.CurrentState!);
            Initially(
                When(Start)
                    .Then(context => context.Instance.Effects.Add("before"))
                    .ThenAsync(async context =>
                    {
                        context.Instance.Effects.Add("async-start");
                        AsyncStarted.SetResult();
                        await release;
                        context.Instance.Effects.Add("async-end");
                    })
                    .TransitionTo(Active));
        }

        public TaskCompletionSource AsyncStarted { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);

        public State Active { get; private set; } = null!;

        public Event Start { get; private set; } = null!;
    }

    private sealed class FailureMachine : AutomatonymousStateMachine<OrderState>
    {
        public FailureMachine()
        {
            InstanceState(instance => instance.CurrentState!);
            Initially(
                When(Fail)
                    .Then(context => context.Instance.Effects.Add("before"))
                    .Then(_ => throw new TestFailureException("expected"))
                    .Then(context => context.Instance.Effects.Add("after"))
                    .TransitionTo(Active));
        }

        public State Active { get; private set; } = null!;

        public Event Fail { get; private set; } = null!;
    }

    private sealed class IgnorePrecedenceMachine : AutomatonymousStateMachine<OrderState>
    {
        public IgnorePrecedenceMachine()
        {
            InstanceState(instance => instance.CurrentState!);
            During(Active, When(Refresh).Ignore());
            DuringAny(
                When(Refresh)
                    .Then(context => context.Instance.Effects.Add("fallback"))
                    .TransitionTo(Suspended));
        }

        public State Active { get; private set; } = null!;

        public State Suspended { get; private set; } = null!;

        public Event Refresh { get; private set; } = null!;
    }

    private sealed class TypedPayloadMachine : AutomatonymousStateMachine<OrderState>
    {
        public TypedPayloadMachine()
        {
            InstanceState(instance => instance.CurrentState!);
            Initially(
                When(Update)
                    .Then(context =>
                    {
                        ObservedPayload = context.Data;
                        context.Instance.Effects.Add($"first:{context.Data.Quantity}");
                    })
                    .ThenAsync(context =>
                    {
                        context.Instance.Effects.Add($"second:{context.Data.Quantity}");
                        return Task.CompletedTask;
                    })
                    .TransitionTo(Active));
        }

        public State Active { get; private set; } = null!;

        public Event<QuantityUpdate> Update { get; private set; } = null!;

        public QuantityUpdate? ObservedPayload { get; private set; }
    }

    private sealed class TypedAsyncMachine : AutomatonymousStateMachine<OrderState>
    {
        public TypedAsyncMachine()
        {
            InstanceState(instance => instance.CurrentState!);
            State(() => Active);
            Event(() => Start);
            Event(() => IgnoreMe);

            Initially(
                When(Start)
                    .ThenAsync(context =>
                    {
                        context.Instance.Quantity = context.Data;
                        return Task.CompletedTask;
                    })
                    .TransitionTo(Active));

            During(Active, Ignore(IgnoreMe));
        }

        public State Active { get; private set; } = null!;

        public Event<int> Start { get; private set; } = null!;

        public Event<string> IgnoreMe { get; private set; } = null!;
    }

    private sealed class TypedFinalizeMachine : AutomatonymousStateMachine<OrderState>
    {
        public TypedFinalizeMachine()
        {
            InstanceState(instance => instance.CurrentState!);
            Initially(When(Complete).Finalize());
        }

        public Event<int> Complete { get; private set; } = null!;
    }

    private sealed class TestFailureException(string message) : Exception(message);

    private sealed record QuantityUpdate(int Quantity);
}
